css:
.fx-art{position:relative;overflow:hidden;background:linear-gradient(135deg,var(--primary),color-mix(in srgb,var(--primary) 45%,var(--accent)))}
.fx-art::before,.fx-art::after{content:"";position:absolute;border-radius:50%;background:color-mix(in srgb,var(--accent) 60%,#fff);opacity:.35}
.fx-art::before{width:60%;aspect-ratio:1;right:-12%;top:-20%}.fx-art::after{width:38%;aspect-ratio:1;left:8%;bottom:-18%;opacity:.25;background:#fff}
.fx-art.a2{background:linear-gradient(160deg,var(--accent),color-mix(in srgb,var(--accent) 40%,var(--primary)))}
.fx-art.a3{background:linear-gradient(200deg,color-mix(in srgb,var(--primary) 70%,#000),var(--accent))}
.fx-tilt .grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1.6em;width:min(1060px,100%)}
.fx-tilt .card{background:color-mix(in srgb,var(--surface) 94%,var(--text));border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;display:flex;flex-direction:column}
.fx-tilt .card .fx-art{aspect-ratio:16/10}
.fx-tilt .card .body{padding:1.2em 1.3em 1.4em;display:grid;gap:.55em}
.fx-tilt .card .tag{justify-self:start;font-size:.72em;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:var(--accent)}
.fx-tilt .card h3{font-size:1.35em}.fx-tilt .card p{opacity:.7;font-size:.95em}
.fx-tilt .card a{color:var(--primary);font-weight:700;text-decoration:none;font-size:.92em;margin-top:.3em}
@media(max-width:820px){.fx-tilt .grid{grid-template-columns:1fr}}
.fx-tilt .grid{perspective:1100px}
.fx-tilt .card{position:relative;transform-style:preserve-3d;transition:transform calc(.25s/var(--speed)) ease-out;will-change:transform}
.fx-tilt .card::after{content:"";position:absolute;inset:0;pointer-events:none;border-radius:inherit;opacity:0;transition:opacity .3s;background:radial-gradient(circle at var(--gx,50%) var(--gy,0%),rgba(255,255,255,.35),transparent 55%)}
.fx-tilt .card:hover::after{opacity:1}
/* touch: :hover mirrored as .is-tap */
.fx-tilt .card.is-tap::after{opacity:1}

