/* touch: tilt while the finger is down */
if(matchMedia('(pointer:coarse)').matches&&!matchMedia('(prefers-reduced-motion:reduce)').matches){
document.querySelectorAll('.fx-tilt .card').forEach(function(c){function t(e){var r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;c.style.transform='rotateY('+(x-.5)*14+'deg) rotateX('+(.5-y)*14+'deg) translateZ(8px)';c.style.setProperty('--gx',x*100+'%');c.style.setProperty('--gy',y*100+'%')}
c.addEventListener('pointerdown',t);c.addEventListener('pointermove',function(e){if(e.pressure>0||e.buttons)t(e)});
function up(){c.style.transform=''}c.addEventListener('pointerup',up);c.addEventListener('pointercancel',up)})}
(function(){if(!matchMedia('(hover:hover) and (pointer:fine)').matches||matchMedia('(prefers-reduced-motion:reduce)').matches)return;
document.querySelectorAll('.fx-tilt .card').forEach(function(c){c.addEventListener('mousemove',function(e){var r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width,y=(e.clientY-r.top)/r.height;
c.style.transform='rotateY('+(x-.5)*14+'deg) rotateX('+(.5-y)*14+'deg) translateZ(8px)';c.style.setProperty('--gx',x*100+'%');c.style.setProperty('--gy',y*100+'%')});
c.addEventListener('mouseleave',function(){c.style.transform=''})})})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
